const items = $input.all();
const ZONE_LABELS = { ZONA_A: 'Orquideario', ZONA_B: 'Jardín', ZONA_C: 'Terraza', ZONA_D: 'Ventanas', EXTERIOR: 'Exterior' };
const results = [];

function formatZones(zones) {
  if (!zones) return 'General';
  let arr = Array.isArray(zones) ? zones : [zones];
  if (typeof zones === 'string' && zones.startsWith('{')) {
    arr = zones.replace(/[{}]/g, '').split(',');
  }
  return arr.map(z => ZONE_LABELS[z.trim()] || z.trim()).join(', ');
}

for (const item of items) {
  const row = item.json;
  if (!row.notif_id) continue;

  let replyText = '';
  let keyboard = null;

  // CASO 1: Mantenimiento de Filtro de Agua
  if (row.type === 'MAINTENANCE_REMINDER') {
    replyText = `\u200B\n*Mantenimiento de Filtro de Agua*\n\n` +
      (row.description || 'Han transcurrido 48 horas desde la última limpieza del filtro de agua. Por favor realizar el mantenimiento antes del riego de las 11:00 AM.');

    keyboard = {
      inline_keyboard: [
        [{ text: '✅ Filtro Limpiado', callback_data: `filter_cleaned:${row.notif_id}` }]
      ]
    };
  }
  // CASO 2: Confirmación de Tanque de Agroquímicos (Hardware)
  else if (row.type === 'AGROCHEMICAL_CONFIRM' && row.taskId) {
    const dateObj = row.hw_scheduled_at ? new Date(row.hw_scheduled_at) : new Date();
    const timeStr = dateObj.toLocaleTimeString('es-VE', { hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'America/Caracas' });
    const zonesStr = formatZones(row.hw_zones);

    replyText = `\u200B\n*Confirmación de Tanque de Agroquímicos*\n\n` +
      `Rutina: ${row.hw_schedule_name || 'Riego Agroquímico'}\n` +
      (row.hw_agrochemical_name ? `Producto: ${row.hw_agrochemical_name}\n` : '') +
      (row.hw_preparation ? `Receta: ${row.hw_preparation}\n` : '') +
      `Zonas: ${zonesStr}\n` +
      `Hora Programada: ${timeStr}\n\n` +
      `¿El tanque de mezcla se encuentra preparado para la ejecución automática?`;

    keyboard = {
      inline_keyboard: [
        [{ text: '✅ Confirmar Tanque', callback_data: `agro_hw_confirm:${row.taskId}:${row.notif_id}` }],
        [
          { text: '⏱️ Posponer 24h', callback_data: `agro_hw_postpone:${row.taskId}:24:${row.notif_id}` },
          { text: '⏱️ Posponer 48h', callback_data: `agro_hw_postpone:${row.taskId}:48:${row.notif_id}` }
        ],
        [{ text: '❌ Cancelar', callback_data: `agro_hw_cancel:${row.taskId}:${row.notif_id}` }]
      ]
    };
  }
  // CASO 3: Recordatorio de Dosificación Manual (Laboratorio / DosingLog)
  else if (row.type === 'AGROCHEMICAL_CONFIRM' && row.dosingLogId) {
    const dateObj = row.manual_scheduled_at ? new Date(row.manual_scheduled_at) : new Date();
    const timeStr = dateObj.toLocaleTimeString('es-VE', { hour: '2-digit', minute: '2-digit', hour12: true, timeZone: 'America/Caracas' });
    const zonesStr = formatZones(row.manual_zones);

    replyText = `\u200B\n*Dosificación Manual Programada*\n\n` +
      `Rutina: ${row.manual_schedule_name || 'Dosificación Manual'}\n` +
      (row.manual_agrochemical_name ? `Producto: ${row.manual_agrochemical_name}\n` : '') +
      (row.manual_preparation ? `Receta: ${row.manual_preparation}\n` : '') +
      `Zonas: ${zonesStr}\n` +
      `Hora: ${timeStr}`;

    keyboard = {
      inline_keyboard: [
        [{ text: '✅ Marcar como Completada', callback_data: `dosing_manual_confirm:${row.dosingLogId}:${row.notif_id}` }]
      ]
    };
  }
  // CASO 4: Notificación Genérica del Sistema
  else {
    replyText = `\u200B\n*${row.title || 'Notificación del Sistema'}*\n\n` +
      (row.description || '');
  }

  results.push({
    json: {
      notifId: row.notif_id,
      replyText,
      hasKeyboard: keyboard !== null,
      keyboard: keyboard || {}
    }
  });
}

return results;
